package com.example.rokidkeyboardbridge;
import java.io.*;import org.json.*;
/** Bounded SSE reader. A truncated stream is never a completed answer. */
public final class ConversationStream {
 public interface Preview{void update(String text)throws Exception;}
 public static String read(InputStream stream,Preview preview)throws Exception{
  BufferedReader in=new BufferedReader(new InputStreamReader(stream,"UTF-8"));StringBuilder event=new StringBuilder(),text=new StringBuilder();JSONArray other=new JSONArray();JSONObject result=new JSONObject(),candidate=new JSONObject();boolean finished=false;int total=0;String line;
  while((line=in.readLine())!=null){total+=line.length();if(total>4000000||line.length()>1000000)throw new IOException("STREAM_LIMIT");if(line.isEmpty()){if(event.length()>0){JSONObject chunk=new JSONObject(event.toString());event.setLength(0);if(chunk.has("error"))throw new IOException("STREAM_ERROR");if(chunk.has("promptFeedback"))result.put("promptFeedback",chunk.get("promptFeedback"));JSONArray cs=chunk.optJSONArray("candidates");if(cs==null||cs.length()==0)continue;JSONObject c=cs.getJSONObject(0);if(c.optInt("index",0)!=0)throw new IOException("STREAM_INDEX");JSONArray parts=c.optJSONObject("content")==null?null:c.getJSONObject("content").optJSONArray("parts");if(parts!=null)for(int i=0;i<parts.length();i++){JSONObject part=parts.getJSONObject(i);if(part.optBoolean("thought"))continue;if(part.has("text")){text.append(part.getString("text"));if(text.length()>200000)throw new IOException("STREAM_LIMIT");preview.update(text.toString());}else other.put(part);}for(String key:new String[]{"finishReason","safetyRatings","groundingMetadata","citationMetadata"})if(c.has(key))candidate.put(key,c.get(key));if(c.has("finishReason")&&!c.getString("finishReason").isEmpty())finished=true;}continue;}if(line.startsWith("data:")){if(event.length()>0)event.append('\n');event.append(line.substring(5).trim());}}
  if(event.length()>0)throw new IOException("STREAM_TRUNCATED");if(!finished){JSONObject feedback=result.optJSONObject("promptFeedback");if(feedback!=null&&!feedback.optString("blockReason").isEmpty())return result.put("candidates",new JSONArray()).toString();throw new IOException("STREAM_TRUNCATED");}JSONArray parts=new JSONArray();if(text.length()>0)parts.put(new JSONObject().put("text",text.toString()));for(int i=0;i<other.length();i++)parts.put(other.get(i));candidate.put("content",new JSONObject().put("role","model").put("parts",parts));return result.put("candidates",new JSONArray().put(candidate)).toString();
 }
 public static String failure(Throwable error){for(Throwable x=error;x!=null;x=x.getCause()){if(x instanceof java.net.SocketTimeoutException||x instanceof java.net.ConnectException||x instanceof java.net.UnknownHostException||x instanceof java.net.SocketException)return "NETWORK";}return "MODEL_ERROR";}
 public static String display(String answer,int limit){return answer.length()<=limit?answer:answer.substring(0,limit)+"\n（全文は会話ログで確認）";}
}
